rule.sql:
SET
  @nowMs        = timestamp(),
  @day          = floor(@nowMs / 1000 / 86400),
  @thing        = topic(3),
  @transaction  = topic(4),
  @pk           = concat('Camera#', @thing)

SELECT
  @pk AS PK,
  concat('Rec#', @transaction) AS SK,

  @transaction   AS transactionId,
  status  AS status,
  @nowMs AS updatedAt,

  'Recs#ALL' AS allRecordingsPk,
  concat(cast(@nowMs as String), '#', @pk, '#', @transaction) AS allRecordingsSk,

  'Ongoing#ALL' AS ongoingRecordingsPk,
  concat(cast(@nowMs as String), '#', @pk, '#', @transaction) AS ongoingRecordingsSk,

  fps             AS currentFPS,
  bitrate         AS currentBitrate,
  recordedSeconds AS lengthSec,

FROM 'yx/recordings/+/+/status'
WHERE
    @thing = clientid() AND status = 'ONGOING'
